<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\TrustedClient\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Throwable;
use OpenApi\Attributes as OA;
use DateTime;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\Gateway\TrustedClientFilter;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\Gateway\TrustedClientCursor;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientAttributes;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Usecase\List\TrustedClientListUsecase;
use Civi\Lughauth\Shared\Security\AesCypherService;

class TrustedClientListController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly TrustedClientListUsecase $listUsecase,
        private readonly AesCypherService $cypherService,
    ) {
    }
    #[OA\Get(
        path: "/api/access/trusted-clients",
        tags: ["Trusted client"],
        description:"Create",
        responses: [
        new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/TrustedClientApiListDTO")),
        new OA\Response(response: 422, description: "Constraint error"),
    ]
    )
    ]
    public function list(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("List Trusted client");
        $span = $this->startSpan("List Trusted client");
        try {
            $params = $request->getQueryParams();
            $filter = new TrustedClientFilter(
                uids: isset($params['uid']) ? [$params['uid']] : (isset($params['uids']) ? explode(',', $params['uids']) : null),
                search: $params['search'] ?? null,
                code: $params['code'] ?? null,
                withBackChannelUrl: $params['with-back-channel-url'] ?? null,
                withFrontChannelUrl: $params['with-front-channel-url'] ?? null,
            );
            $cursor = new TrustedClientCursor(
                limit: (int)($params['limit'] ?? 100),
                sinceUid: $params['since-uid'] ?? null,
                sinceCode: $params['since-code'] ?? null,
                order: isset($params['order']) ? $this->extractOrder(explode(',', $params['order'])) : null,
            );
            $result = $this->listUsecase->list($filter, $cursor);
            $value = ['items' => array_map(fn (TrustedClientAttributes $item): TrustedClientApiDTO => $this->mapTrustedClient($request, $item), $result->values())];
            $nextLink = $this->nextLink($result->cursor(), $params);
            if (null !== $nextLink) {
                $value['next'] = "?{$nextLink}";
            }
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
              ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function extractOrder(array $order): array
    {
        $this->logDebug("Extract order for Trusted client");
        $span = $this->startSpan("Extract order for Trusted client");
        try {
            $mapped = [];
            foreach ($order as $ord) {
                if ($ord === 'code-asc') {
                    $mapped[] = 'codeAsc';
                }
                if ($ord === 'code-desc') {
                    $mapped[] = 'codeDesc';
                }
            }
            return $mapped;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function nextLink(?TrustedClientCursor $value, array $params): ?string
    {
        $this->logDebug("Check generic allow for Trusted client");
        $span = $this->startSpan("Generic allow for Trusted client");
        try {
            if (!$value) {
                return null;
            }
            $link = [];
            if (isset($params['limit'])) {
                $link['limit'] = 'limit=' . $params['limit'];
            }
            $sinceUid = $value->sinceUid();
            if (null !== $sinceUid) {
                $link['since-uid'] = 'since-uid=' . urlencode($sinceUid);
            }
            $sinceCode = $value->sinceCode();
            if (null !== $sinceCode &&  false !== strpos($params['order'] ?? '', 'CODE-ASC')) {
                $link['since-code'] = 'since-code=' . urlencode($sinceCode);
            }
            $sinceCode = $value->sinceCode();
            if (null !== $sinceCode &&  false !== strpos($params['order'] ?? '', 'CODE-DESC')) {
                $link['since-code'] = 'since-code=' . urlencode($sinceCode);
            }
            return implode('&', $link);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapTrustedClient(ServerRequestInterface $request, TrustedClientAttributes $value): TrustedClientApiDTO
    {
        $this->logDebug("Map entity to output dto for Trusted client");
        $span = $this->startSpan("Map entity to output dto for Trusted client");
        try {
            $dto = new TrustedClientApiDTO();
            $dto->uid = $value->getUid();
            $dto->code = $value->getCode();
            $dto->allowAllScopes = $value->isAllowAllScopes();
            $dto->publicAllow = $value->isPublicAllow();
            $allowedRedirects = [];
            $existentsAllowedRedirects = $value->getAllowedRedirects();
            if (null !== $existentsAllowedRedirects) {
                foreach ($allowedRedirects as $item) {
                    $allowedRedirects[] = [
                    'uid' => $item->uid(),
                    'url' => $item->getUrl(),
                    'version' => $item->getVersion(),
                    ];
                }
            }
            $dto->allowedRedirects = $allowedRedirects;
            $dto->secretOauth = '******';
            $dto->backChannelLogoutUri = $value->getBackChannelLogoutUri();
            $dto->backChannelLogoutSessionRequired = $value->isBackChannelLogoutSessionRequired();
            $dto->frontChannelLogoutUri = $value->getFrontChannelLogoutUri();
            $dto->frontChannelLogoutSessionRequired = $value->isFrontChannelLogoutSessionRequired();
            $dto->enabled = $value->isEnabled();
            $dto->registrationAccess = $value->getRegistrationAccess();
            $dto->clientName = $value->getClientName();
            $dto->logoUri = $value->getLogoUri();
            $dto->clientUri = $value->getClientUri();
            $dto->policyUri = $value->getPolicyUri();
            $dto->tosUri = $value->getTosUri();
            $dto->tokenEndpointAuthMethod = $value->getTokenEndpointAuthMethod();
            $dto->grantTypesJson = $value->getGrantTypesJson();
            $dto->responseTypesJson = $value->getResponseTypesJson();
            $dto->dynamicallyRegistered = $value->isDynamicallyRegistered();
            $dto->registeredAt = $value->getRegisteredAt()?->format(DateTime::ATOM);
            $dto->allowedScopesM2m = $value->getAllowedScopesM2m();
            $dto->m2mTokenTtlSeconds = $value->getM2mTokenTtlSeconds();
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
